import React, { useState } from "react";
import { searchMovies } from "../api/movieApi"; // 경로는 상황에 맞게 조정

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    try {
      const results = await searchMovies(query);
      setMovies(results);
    } catch (error) {
      console.error("영화 검색 중 오류 발생:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="p-4 max-w-xl mx-auto">
      <h1 className="text-xl font-bold mb-4">🎬 영화 검색</h1>
      <div className="flex gap-2 mb-4">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyPress}
          placeholder="영화 제목을 입력하세요"
          className="flex-1 border px-3 py-2 rounded"
        />
        <button onClick={handleSearch} className="px-4 py-2 bg-blue-500 text-white rounded">
          검색
        </button>
      </div>

      {loading ? (
        <p>검색 중...</p>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {movies.map((movie) => (
            <div key={movie.id} className="border rounded p-2 shadow-sm">
              <img
                src={
                  movie.poster_path
                    ? `https://image.tmdb.org/t/p/w200${movie.poster_path}`
                    : "https://via.placeholder.com/200x300?text=No+Image"
                }
                alt={movie.title}
                className="mb-2 w-full"
              />
              <h2 className="text-sm font-semibold">{movie.title}</h2>
              <p className="text-xs text-gray-600">{movie.release_date}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SearchPage;
